{
  "team": {"name": "billing-platform", "repo_url": "https://github.com/acme/billing", "record_version": "1.0.0"},
  "owner": "swe:bob",
  "inputs": [
    {"name": "tool_task_map", "value": [
      {"task_class": "boilerplate-scaffolding", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "unit-tests", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "refactor", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "code-review", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "documentation", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "data-migration", "tool": "copilot", "checkpoint": "self-review"},
      {"task_class": "infrastructure", "tool": "copilot", "checkpoint": "one-reviewer"}
    ]},
    {"name": "block_list", "value": [
      {"area": "payments-billing", "paths": ["src/billing/charges/**"], "policy": "two-reviewers-non-prompter"}
    ]},
    {"name": "context_files", "value": []},
    {"name": "exclusion_file", "value": {"path": ".gitignore", "excludes": [".env"]}},
    {"name": "tool_retention", "value": [
      {"tool": "copilot", "terms_checked": false, "source": "https://github.com/features/copilot"}
    ]},
    {"name": "prompt_template", "value": {"path": "none", "blocks": ["Task"]}},
    {"name": "ai_assisted_label", "value": {"label": "", "auto_merge_disabled": false}}
  ],
  "decision": "We use Copilot for everything.",
  "evidence": ["https://github.com/acme/billing"],
  "review": {
    "cadence": "quarterly",
    "next_review_at": "2026-12-01",
    "last_outcome": {
      "period": "2026-Q2",
      "ai_assisted": {"pr_count": 80, "defect_escape_rate": 0.09, "revert_rate": 0.06, "churn_2w_rate": 0.31},
      "other": {"pr_count": 20, "defect_escape_rate": 0.04, "revert_rate": 0.02, "churn_2w_rate": 0.08},
      "worse_on": ["defect_escape_rate", "revert_rate", "churn_2w_rate"],
      "map_tightened": false,
      "url": "https://grafana.example.com/d/pr-quality"
    }
  }
}
